from collections import defaultdict

def find_l_shape_corners(grid):
    positions = defaultdict(list)
    background = 2
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != background:
                positions[grid[r][c]].append((r, c))

    l_shapes = {}
    corners = {}

    for color, pos in positions.items():
        if len(pos) == 3:
            # Check if it's an L-shape (corner has exactly 2 neighbors)
            for p in pos:
                neighbors = sum(1 for o in pos if o != p and abs(o[0]-p[0]) + abs(o[1]-p[1]) == 1)
                if neighbors == 2:
                    l_shapes[color] = (pos, p)
                    corners[color] = p
                    break

    return l_shapes, corners

