def find_connected_groups(grid, color):
    groups = []
    seen = set()
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == color and (r, c) not in seen:
                group = [(r, c)]
                seen.add((r, c))
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            group.append((nr, nc))
                            queue.append((nr, nc))
                if len(group) >= 2:
                    groups.append(group)
    return groups

