def generate_output(test_input):
    # Start with background
    output = [[2 for _ in range(9)] for _ in range(9)]

    # Copy all non-background cells to output (they stay in place)
    for r in range(9):
        for c in range(9):
            if test_input[r][c] != 2:
                output[r][c] = test_input[r][c]

    # For each L-shape, extend diagonal
    for color, corner, group, d1, d2, diag in l_shapes:
        r, c = corner
        # Start diagonal 2 steps from corner
        start_r, start_c = r + 2*diag[0], c + 2*diag[1]

        rr, cc = start_r, start_c
        while 0 <= rr < 9 and 0 <= cc < 9:
            # Check if adjacent to any existing cell of same color
            is_adjacent_to_same = False
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                adj_r, adj_c = rr + dr, cc + dc
                if output[adj_r][adj_c] == color:
                    is_adjacent_to_same = True
                    break

            # Check if adjacent to L-cells specifically
            is_adjacent_to_L = False
            for lr, lc in group:
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    if (rr + dr == lr and cc + dc == lc) and (rr, cc) != (lr, lc):
                        is_adjacent_to_L = True
                        break
                if is_adjacent_to_L:
                    break

            if not is_adjacent_to_L:
                output[rr][cc] = color
            else:
                # Skip cell adjacent to L
                pass  # Keep background

            rr += diag[0]
            cc += diag[1]

    return output

